//! The "is an Arduino header" capability.

use crate::gpio::PinId;

/// An Arduino header pin (`D0`–`D13`, `A0`–`A5`) of the selected board, as
/// opposed to a board-internal pin (`UsbMux`, `Sci1Tx`, `Sci9Tx`, …) that
/// the HAL hands out for its own drivers: driving one of those as a plain
/// output would break what it is wired to (the ESP32-S3 bridge's UART, the
/// USB mux). Every header pin can drive an output: the RA4M1's input-only
/// pins (P200, P214, P215; manual §19.2) are on no header. Generated by
/// [`pin_map`](crate::gpio::pin_map) for headers only. Sealed.
#[diagnostic::on_unimplemented(
    message = "`{Self}` is a board-internal pin, not an Arduino header",
    label = "needs a header pin: D0–D13 or A0–A5"
)]
pub trait HeaderPin: PinId {}
